    "explanation": "Choice B is the best answer because it presents the conclusion that most logically follows from the text’s discussion of the chemical content of pigments. The text begins by differentiating between two kinds of pigments: mineral-based pigments such as red ocher, which get their color from iron oxide, and plant-based pigments, which have a high level of carbon. The text then goes on to describe an analysis by archaeologists of the pigment of decorated beads made by members of the Natufian culture around 15,000 years ago. The archaeologists found that the red pigment on some of the beads contained no iron but had a high level of carbon. Since red ocher gets its color from iron oxide, while plant-based pigments have a high level of carbon, the researchers concluded that the Natufian beadmakers used plant-based pigments to decorate some of the beads examined in the study.\n Choice A is incorrect because the text does not indicate that the Natufians were the first to use plant-based pigments, so it cannot be concluded that the beads in the study were the oldest surviving examples of the use of plant-based pigments for decorating beads.\n Choice C is incorrect because the text does not compare the brightness of plant-based and mineral-based pigments.\n Choice D is incorrect. While it can be concluded that the Natufian beadmakers used plant-based pigments because the pigment found on several beads had a high level of carbon, the text offers no evidence that ocher was difficult to find."
