    "explanation": "Choice C is the best answer because it most logically completes the text’s discussion of parthenogenesis as it relates to two California condors at the San Diego Zoo. The text explains that parthenogenesis is a form of reproduction in which a female reproduces without mating, producing an egg containing an offspring with DNA that comes entirely from its mother. After noting examples of parthenogenesis among birds, the text then reports on a discovery at the San Diego Zoo. According to the text, scientists at the zoo found that two of the zoo’s California condors weren’t similar enough to any of the zoo’s male condors to be their offspring. Given that parthenogenesis occurs without mating and results in an offspring with DNA entirely from its mother, it can reasonably be inferred that the scientists concluded that the mothers of the two condors probably didn’t mate with any of the male condors at the zoo, reproducing through parthenogenesis instead.\n Choice A is incorrect because the text never suggests that at least one of the condors’ mothers was born as a result of parthenogenesis. Rather, the text suggests that the two condors were themselves both probably born as a result of parthenogenesis, which would account for their lack of strong genetic resemblance to any of the male condors in the zoo’s condor enclosure.\n Choice B is incorrect because the text never discusses wild California condors, only California condors living at the San Diego Zoo. For this reason, the text doesn’t support a conclusion that distinguishes between how California condors reproduce in zoos and how they reproduce in the wild.\n Choice D is incorrect because the text never suggests that the zoo’s female condors lacked sufficient access to males or that this would be a cause of parthenogenesis, indicating only that the condor enclosure included males."
