    "correctAnswer": "C",
    "explanation": "Choice C is the best answer because it most logically completes the text’s discussion of the influence of decision-making modes on consumers’ choices of different electricity plans. The Affect Mode describes choices based on the decision-maker’s preferred emotional outcome, the Role Mode describes choices based on the decision-maker’s social motivations, and the Calculation Mode describes choices based on minimizing financial costs and maximizing the decision-maker’s convenience. Thus, if those using a Calculation Mode disfavor the green plan, it would be due to some financial or convenience burden the green plan imposes that the other doesn’t. The text indicates that the green plan had a lower financial cost but was nonetheless rejected by participants using the Calculation Mode. It therefore follows that the green plan likely imposed a convenience burden that outweighed potential financial savings for these participants.\n Choice A is incorrect. According to the text, the Affect Mode involves the decision-maker’s preferred emotional outcome, the Role Mode involves social motivations, and the Calculation Mode is oriented toward minimizing financial costs and maximizing the decision-maker’s convenience. Thus, unlike the Affect or Role Modes, the Calculation Mode would almost certainly involve taking price differences into account.\n Choice B is incorrect. According to the text, the Affect Mode involves the decision-maker’s preferred emotional outcome, the Role Mode involves social motivations, and the Calculation Mode is oriented toward minimizing financial costs and maximizing the decision-maker’s convenience. Thus, there is no reason to think that participants using the Calculation Mode at any point took social responsibility into account, let alone think that they discovered a disparity between their expectations and reality.\n Choice D is incorrect. According to the text, the Affect Mode involves the decision-maker’s preferred emotional outcome, the Role Mode involves social motivations, and the Calculation Mode is oriented toward minimizing financial costs and maximizing the decision-maker’s convenience. Thus, the text doesn’t indicate that cost-effectiveness is a factor for participants using the Affect or Role Modes, and there is no basis to compare their beliefs in the truthfulness of the green-plan description with those of the Calculation Mode users."
