    "subtopicId": "inferences",
    "subtopic": "Inferences",
    "difficulty": "hard",
    "passage": "Outi Tervo and team studied the effect of human-caused noise on narwhals (Monodon monoceros), arctic marine mammals that are sensitive to acoustic changes in their environment. Hypothesizing that elevated sound levels affect foraging among narwhals, Tervo’s team compared narwhal diving behaviors in natural sound conditions with those behaviors in two human-caused sound exposure conditions—ship sounds and ship sounds coupled with sonic pulses. Both exposure conditions resulted in significant decreases in the number and target depth of deep dives (associated with foraging) relative to natural conditions. However, differences between diving behaviors in the two exposure types were negligible, a finding that could be attributed to the fact that ______",
    "stem": "Which choice most logically completes the text?",
    "type": "mcq",
    "options": [
      {
        "id": "A",
        "text": "sonic pulses can be heard at significantly greater ocean depths than ship sounds can."
      },
      {
        "id": "B",
        "text": "ship sounds contribute so much to the overall sound level that the addition of sonic pulses has little effect on the narwhals’ auditory environment."
      },
      {
        "id": "C",
        "text": "narwhals forage at shallower depths in the presence of ship sounds alone than in the presence of ship sounds coupled with sonic pulses."
      },
      {
        "id": "D",
        "text": "the narwhals weren’t as sensitive to human-caused sounds as the researchers had predicted."
      }
    ],
    "correctAnswer": "B",
    "explanation": "Choice B is the best answer because it most logically completes the text’s discussion of human-caused noise and narwhal behavior. The text establishes that Outi Tervo and team found that while both ship sounds alone and ship sounds coupled with sonic pulses significantly affected narwhal foraging behaviors compared to natural conditions, there were negligible differences between the narwhals’ responses to the two sound exposure types (a somewhat surprising finding because one might expect that adding sonic pulses would have an even greater impact). It logically follows that if ship sounds are already so loud that adding sonic pulses to them doesn’t substantially increase the level of human- caused sound exposure, the two conditions would produce essentially the same behavioral responses because the additional sonic pulses are essentially irrelevant.\n Choice A is incorrect because the fact that sonic pulses are audible at greater depths than are ship sounds would be more likely to help explain a difference—not a similarity—in how the narwhals responded to the two types of sound exposure. If at some points during the study the narwhals were at depths where only sonic pulses (but not ship sounds) could be heard, then they might be expected to alter their diving behavior more dramatically in response to those pulses. But since the text reports negligible differences between diving behaviors in the two exposure types, the fact that sonic pulses reach greater depths than do ship sounds has little explanatory power in this context.\n Choice C is incorrect because the idea that the narwhals foraged at shallower depths in one of the two exposure conditions directly contradicts the information given in the text. The text states that there were negligible differences in the narwhals’ diving behaviors between the two conditions, meaning that the behaviors were essentially the same.\n Choice D is incorrect. Although the text states that two conditions with human-caused sounds (ship sounds alone and ship sounds coupled with sonic pulses) had essentially the same effect on narwhals’ deep dives, this indicates only that sonic pulses didn’t meaningfully change the effect of ship sounds, not that the narwhals were less sensitive to human-caused sounds than predicted. Indeed, the text makes it clear that the sounds significantly altered the narwhals’ behavior."
