    "correctAnswer": "C",
    "explanation": "Choice C is the best answer because it most logically completes the text’s discussion of Johny Isla and the whalelike geoglyph. The text indicates that the German exhibit about the Nazca Lines included a photograph showing a whalelike geoglyph that Isla hadn’t known about before attending the exhibit, even though Isla “specializes in” Nazca Lines geoglyphs. Given his expertise, and his surprise at being unfamiliar with the whale glyph, the text strongly suggests that Isla believed he would have noticed the glyph if he had been to its location. Thus, the text implies that the whalelike geoglyph is likely in a location Isla had not previously been to.\n Choice A is incorrect because the text doesn’t address either the species of whale that the geoglyph is meant to represent or its relationship to the earliest humans in the area that is now Peru.\n Choice B is incorrect. Although the text indicates that the photograph of the whalelike geoglyph was on display at a “German exhibit,” that exhibit was specifically “about the Nazca Lines,” which the text indicates are located in Peru. Choice D is incorrect. Although the text does indicate that the glyphs were created “over a period of many centuries,” the text doesn’t address when in that period of time any particular glyphs were created."
